MATCH_PLUGIN.COMMAND_LINE:
$Res = 0

$ClassRegPath = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class'
$SoftwareComponentClassRegPath = $ClassRegPath + '\{5c4c3332-344d-483c-8739-259e934c9cc8}'
$AudioProcessingObjectRegPath = $ClassRegPath + '\{5989fce8-9cd0-467d-8a6a-5419e31529d4}'
[Version]$MinVersion = [Version]::New('24.1.0.3')
$DriverDesc = 'CriDspApo Component Device'

# Find 'CriDspApo Component Device' Class entries
$ComponentRegKey = Get-ChildItem -Path $SoftwareComponentClassRegPath,$AudioProcessingObjectRegPath -ErrorAction SilentlyContinue | Where-Object { $_.GetValue('DriverDesc') -match $DriverDesc }

if ($ComponentRegKey) {
    [Version]$HighestInstalledVersion = [Version]::New('0.0.0.0')

    foreach ($Key in $ComponentRegKey) {
        $DriverVersionStr = $Key.GetValue('DriverVersion')

        try {
            [Version]$AuxDriverVersion = [Version]::New($DriverVersionStr)

            if ($AuxDriverVersion -ge $HighestInstalledVersion) {
                $HighestInstalledVersion = $AuxDriverVersion
            }
        }
        catch {
            # Couldn't parse DriverVersion. Do nothing.
        }
    }

    if ($HighestInstalledVersion -ge $MinVersion) {
        $Res = 1
    } else { 
        $Res = 0
    }

} else {
    # Couldn't find 'CriDspApo Component Device' Class entry.
    $Res = 0
}

Write-Host 'Final result:', $Res
